INSERT INTO cms_page_revisions (id,page_id,locale,version,slug,title,description,body_markdown,created_by_user_id,created_at) VALUES ('seed:docs:getting-started:en:v1','seed:docs:getting-started','en',1,'getting-started','Getting started','Publish a source request and understand the SourceBoard workflow.','## Create a source request

Start with one image and a focused question. Add the context you already know instead of guessing at a creator or origin.

- Choose the correct visibility before publishing.
- Mark sensitive imagery accurately.
- Keep the title specific enough that people can investigate the same question.

## Follow the evidence trail

Comments can contribute candidate sources, context and links. A useful source answer should make it possible for another person to verify the claim independently.

## Resolve the request

The post author may accept a source when the evidence answers the request. SourceBoard records that Accepted Source separately from later verification or moderation state.',NULL,0);
--> statement-breakpoint
