INSERT INTO cms_page_revisions (id,page_id,locale,version,slug,title,description,body_markdown,created_by_user_id,created_at) VALUES ('seed:docs:comments:en:v1','seed:docs:comments','en',1,'comments','Comments and discussion','Replies, source leads, reactions, media and closed discussions.','## Add useful context

Comments support Markdown, source links and eligible media. Prefer information that advances the source trail over speculation or repeated guesses.

## Closed comments

After a source has been accepted, the post author can close comments. Existing discussion remains visible, while the server rejects new comments until the author reopens the discussion when that action is available.

## Editing, deletion and moderation

Edits and deletes update the visible discussion without requiring a manual page refresh. Moderated or removed content may retain internal audit data even when it is no longer publicly visible.',NULL,0);
--> statement-breakpoint
