INSERT INTO cms_page_revisions (id,page_id,locale,version,slug,title,description,body_markdown,created_by_user_id,created_at) VALUES ('seed:docs:friends:en:v1','seed:docs:friends','en',1,'friends','Friends and discovery','Requests, accepted friends, discovery, blocks and profile privacy.','## Friend requests

Friend requests are private account state. Incoming and outgoing requests stay separate until accepted, and a user can disable new requests through supported privacy settings.

## Friendship does not override privacy

Server-side policy still decides whether a viewer can access a profile or friends-only content. Blocking takes precedence over friendship and discovery surfaces.',NULL,0);
