INSERT INTO cms_page_revisions (id,page_id,locale,version,slug,title,description,body_markdown,created_by_user_id,created_at) VALUES ('seed:docs:account-verification:en:v1','seed:docs:account-verification','en',1,'account-verification','Account and email verification','Registration, Google sign-in, Firebase email verification and sessions.','## Registration security

Registration uses Cloudflare Turnstile and server-side validation. Security checks are part of the authentication flow rather than decorative client-only controls.

## Firebase verification handoff

When Firebase verifies an email, SourceBoard synchronizes that verified identity instead of requiring an unrelated second verification. Verification links may return with Firebase''s oobCode and continue through the SourceBoard handoff.

## Sessions

Sessions are server-managed and can be invalidated by account security or moderation actions. Signing out ends the current browser session; supported security controls may end other sessions as well.',NULL,0);
--> statement-breakpoint
