INSERT INTO cms_page_revisions (id,page_id,locale,version,slug,title,description,body_markdown,created_by_user_id,created_at) VALUES ('seed:docs:moderation-and-reports:en:v1','seed:docs:moderation-and-reports','en',1,'moderation-and-reports','Moderation and reports','Reporting content, sanctions, Source Integrity and administrative audit trails.','## Report content

Use the report action for spam, harassment, misleading sources, sensitive content, privacy issues, copyright concerns or other policy problems. Reports are reviewed separately from public discussion.

## Moderation actions

Administrative actions can include posting/comment restrictions, suspension, bans, role changes, session invalidation and account handling. Strong actions require server-side capability checks and an audit reason.

## Source Integrity

Accepted Sources can be reviewed as accepted, disputed, suspicious, verified or revoked without collapsing those states into a separate competing verification system.',NULL,0);
--> statement-breakpoint
