INSERT INTO cms_page_revisions (id,page_id,locale,version,slug,title,description,body_markdown,created_by_user_id,created_at) VALUES ('seed:legal:terms:en:v1','seed:legal:terms','en',1,'terms','Terms of Use','Baseline terms for using SourceBoard and contributing public content.','## Using the service

Use SourceBoard only in ways permitted by applicable law and these product policies. Features, limits and availability can change as the service evolves.

## Your contributions

You remain responsible for content you submit and for having the rights or lawful basis needed to submit it. SourceBoard''s source-resolution labels do not grant ownership of third-party work.

## Enforcement

SourceBoard may restrict or remove access when needed to enforce product rules, protect users or operate the service. This summary is product documentation and should receive legal review before being treated as final contractual text.',NULL,0);
--> statement-breakpoint
