INSERT INTO cms_page_revisions (id,page_id,locale,version,slug,title,description,body_markdown,created_by_user_id,created_at) VALUES ('seed:legal:privacy:en:v1','seed:legal:privacy','en',1,'privacy','Privacy','What SourceBoard keeps private and what becomes public when you publish.','## Public information

Public profiles, public source requests, visible comments and public source-resolution metadata can be delivered to visitors and crawlers. The interface should make the relevant visibility choice clear before publication.

## Private account data

Email addresses, sessions, moderation notes, administrative data, private or friends-only content and non-public profile information are not intentionally exposed through public pages, sitemaps or structured public metadata.

## Privacy controls

Supported settings govern profile visibility, friend requests, sensitive-content presentation, blocks and other product privacy choices. This page describes current product behavior and requires legal review for jurisdiction-specific privacy obligations.',NULL,0);
--> statement-breakpoint
