INSERT INTO cms_page_revisions (id,page_id,locale,version,slug,title,description,body_markdown,created_by_user_id,created_at) VALUES ('seed:legal:community-guidelines:en:v1','seed:legal:community-guidelines','en',1,'community-guidelines','Community Guidelines','Rules for useful, safe source-finding discussions.','## Prefer evidence over certainty

Do not present an uncertain attribution as established fact. Explain how a link, creator identity or publication relates to the request and correct mistakes when better evidence appears.

## Respect people

Do not use SourceBoard for harassment, threats, targeted abuse, doxxing, impersonation, spam or attempts to expose private personal information.

## Moderation

Report policy violations instead of escalating them in comments. Moderation decisions and Source Integrity decisions can use separate review and audit trails.',NULL,0);
--> statement-breakpoint
