INSERT INTO cms_page_revisions (id,page_id,locale,version,slug,title,description,body_markdown,created_by_user_id,created_at) VALUES ('seed:legal:copyright-and-attribution:en:v1','seed:legal:copyright-and-attribution','en',1,'copyright-and-attribution','Copyright, DMCA and attribution','How source attribution relates to copyright and removal requests.','## Attribution is not ownership

Accepted Source and verification labels are provenance tools. They do not transfer copyright, create a license or replace the rights of the original creator.

## Copyright concerns

SourceBoard should provide a documented process for copyright or takedown requests and preserve enough internal information to investigate them. The final notice-and-takedown procedure, designated contacts and jurisdiction-specific language require legal review before launch.',NULL,0);
