INSERT INTO cms_page_revisions (id,page_id,locale,version,slug,title,description,body_markdown,created_by_user_id,created_at) VALUES ('seed:legal:data-handling:en:v1','seed:legal:data-handling','en',1,'data-handling','Data Handling','Operational storage, private media and account-data boundaries.','## Service data

SourceBoard stores the account, profile, post, comment, relationship, Store, audit and moderation records needed to operate supported features. D1 remains authoritative for application state.

## Media

Uploaded media is stored in object storage and delivered through SourceBoard routes according to the relevant access policy. Private media should not be converted into publicly enumerable object URLs.',NULL,0);
