INSERT INTO cms_page_revisions (id,page_id,locale,version,slug,title,description,body_markdown,created_by_user_id,created_at) VALUES ('seed:legal:ai-public-content:en:v1','seed:legal:ai-public-content','en',1,'ai-public-content','AI and public content','How public SourceBoard pages are made understandable to crawlers and automated systems.','## Machine-readable public pages

Public posts can include semantic HTML, canonical URLs, structured metadata, sitemaps and explicit Accepted Source provenance so search engines and automated systems can understand the public source trail.

## No training promise

Making public content crawlable does not mean SourceBoard can promise that Google, OpenAI or any other external system will index, use or train on a particular page. External systems make their own decisions under their own policies.

## Private data stays out of the public surface

Emails, sessions, moderation notes, admin data, private profiles, friends-only posts and hidden comments are excluded from the intended public crawler and structured-data surface.',NULL,0);
