INSERT INTO cms_page_revisions (id,page_id,locale,version,slug,title,description,body_markdown,created_by_user_id,created_at) VALUES ('seed:docs:support:en:v1','seed:docs:support','en',1,'support','Help and support','What to include when reporting a SourceBoard product problem.','## Report a product problem

Include the page, the action you attempted, what you expected and what actually happened. For visual defects, a screenshot and viewport size are especially useful. Do not include passwords, session cookies or authentication tokens.

## Account or safety issue

Use in-product reporting for content or conduct issues when available. Account-security and privacy incidents should be handled through a dedicated support path before public launch; final contact details still need operational and legal review.',NULL,0);
